mapper.select:
SELECT /* LGUTLC00140.retrieveConcurrentViewerList */ request_id , request_user_id , employee_name , system_code , module_code , program_id , program_name , batch_id , batch_name , schedule_flag , pop_up_alarm_flag , user_check_flag , actual_start_date , actual_end_date , trx_sec , trx_hhmiss , argument_text , status_code , status_code_name , error_flag , error_content , file_id FROM lgcom_batch_log_v WHERE 1 = 1
AND system_code = #{systemCode}
AND module_code = #{moduleCode}
AND program_id = #{programId}
AND request_user_id = #{requestUserId}
AND request_id = #{requestId}
AND pop_up_alarm_flag = #{alarmFlag}
AND schedule_flag = #{scheduleFlag}
AND user_check_flag = #{userCheckFlag}
AND UPPER(program_name) LIKE '%'||UPPER(#{programName}) || '%'
AND actual_start_date >= to_char( trunc( to_date( #{dateFrom}, 'YYYY-MM-DD') ), 'YYYY-MM-DD HH24:MI:SS' )
AND actual_end_date < to_char( trunc( to_date( #{dateTo}, 'YYYY-MM-DD') + 1 ), 'YYYY-MM-DD HH24:MI:SS' )
ORDER BY actual_start_date DESC
